function pickPlace(random = Math.random) {
  return PLACES[Math.floor(random() * PLACES.length)];
}

function placeById(id) {
  return PLACES.find((place) => place.id === id) ?? PLACES[0];
}

return { PLACES,pickPlace,placeById };
